#[inline(always)]
fn weight(&self) -> u64 { u64::from(self.weight) }

#[inline(always)]
fn set_weight(&mut self, weight: u64) -> Result<()> {
    // 合法なCTS更新はQ-alpha以下。拒否時は保存状態を変えない。
    self.weight = u32::try_from(weight).map_err(|_| "CTS compact weight overflow")?;
    Ok(())
}

