#[cfg(khc_mixture_reuse_audit)]
pub(super) fn audit_compact_storage(weight: u64) -> Result<[u64; 3]> {
    let mut node = Node::fresh();
    let before = node.weight();
    let rejected = match node.set_weight(weight) {
        Ok(()) => 0,
        Err(e) if e == "CTS compact weight overflow" => 1,
        Err(e) => return Err(e),
    };
    Ok([rejected, before, node.weight()])
}
